4	ChatMockupSlide	Чат (на весь экран)	Мокап переписки (мессенджер/чат-бот) с последовательным появлением сообщений.	2	{"bot_name": "Telegram Bot", "bot_subtitle": "bot", "bot_avatar": "T", "messages": [{"role": "user", "text": "\\u041f\\u0440\\u0438\\u0432\\u0435\\u0442!", "image": "", "start_time": 0}, {"role": "assistant", "text": "\\u0417\\u0434\\u0440\\u0430\\u0432\\u0441\\u0442\\u0432\\u0443\\u0439\\u0442\\u0435! \\u0427\\u0435\\u043c \\u043c\\u043e\\u0433\\u0443 \\u043f\\u043e\\u043c\\u043e\\u0447\\u044c?", "image": "", "start_time": 1500}]}	{"type": "object", "fields": {"bot_name": {"type": "text", "required": true}, "bot_subtitle": {"type": "text"}, "bot_avatar": {"type": "text"}, "messages": {"type": "array", "min_items": 1, "max_items": 6, "item": {"type": "object", "fields": {"role": {"type": "enum", "options": ["user", "bot", "assistant"]}, "text": {"type": "long_text"}, "image": {"type": "image"}, "start_time": {"type": "time"}}}, "required": true}}}	{"bot_name": "Telegram Bot", "bot_subtitle": "bot", "bot_avatar": "T", "messages": [{"role": "user", "text": "\\u041f\\u0440\\u0438\\u0432\\u0435\\u0442!", "start_time": 0}, {"role": "assistant", "text": "\\u0417\\u0434\\u0440\\u0430\\u0432\\u0441\\u0442\\u0432\\u0443\\u0439\\u0442\\u0435! \\u0427\\u0435\\u043c \\u043c\\u043e\\u0433\\u0443 \\u043f\\u043e\\u043c\\u043e\\u0447\\u044c?", "start_time": 1500}, {"role": "user", "text": "\\u0413\\u0434\\u0435 \\u043c\\u043e\\u044f \\u043f\\u043e\\u0441\\u044b\\u043b\\u043a\\u0430?", "start_time": 2800}, {"role": "assistant", "text": "\\u0423\\u0436\\u0435 \\u0432 \\u043f\\u0443\\u0442\\u0438", "image": "/media/a7565c96031647ae82b78fd55e520fad.jpg", "start_time": 3600}, {"role": "user", "text": "\\u0421\\u043f\\u0430\\u0441\\u0438\\u0431\\u043e)", "image": "/media/7dec272228924bf6a2b369343e95c38a.jpg", "start_time": 4700}], "item_sfx": {"src": "/media/sfx_e02e4f8ec1a94a74ac5f9df8cb105b3f.mp3", "time_offset": 0, "volume": 0.27}}	Подходит: демонстрация диалога с клиентом/ботом, сценарий «было → стало» в общении, кейсы поддержки. Не использовать: когда нужна сухая структура или таблица — это про диалог.
5	CodeComparisonSlide	Сравнение кода	Два окна кода рядом для сравнения (до/после, свой/чужой подход).	2	{"windows": [{"title": "n8n (Code Node)", "color": "#F97316", "file": "FindNewEmails.js", "code": "// \\u041f\\u043e\\u0438\\u0441\\u043a \\u0443\\u043d\\u0438\\u043a\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 email-\\u043e\\u0432\\nlet new_emails = [];\\nfor (let i = 0; i < api_emails.length; i++) {\\n  let found = False;\\n  for (let j = 0; j < db_emails.length; j++) {\\n    if (api_emails[i] === db_emails[j]) {\\n      found = True;\\n      break;\\n    }\\n  }\\n  if (!found) {\\n    new_emails.push(api_emails[i]);\\n  }\\n}\\nreturn new_emails;", "typing": true, "start_time": 554}, {"title": "Python", "color": "#38BDF8", "file": "find_emails.py", "code": "# \\u041f\\u043e\\u0438\\u0441\\u043a \\u0443\\u043d\\u0438\\u043a\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 email-\\u043e\\u0432\\n\\napi_set = set(api_emails)\\ndb_set = set(db_emails)\\n\\nnew_emails = list(api_set - db_set)", "typing": true, "start_time": 2054}]}	{"type": "object", "fields": {"windows": {"type": "array", "min_items": 1, "max_items": 6, "item": {"type": "object", "fields": {"title": {"type": "text"}, "color": {"type": "color"}, "file": {"type": "text"}, "code": {"type": "code"}, "typing": {"type": "boolean"}, "start_time": {"type": "time"}}}, "required": true}}}	{"windows": [{"title": "n8n (Code Node)", "color": "#F97316", "file": "FindNewEmails.js", "code": "// \\u041f\\u043e\\u0438\\u0441\\u043a \\u0443\\u043d\\u0438\\u043a\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 email-\\u043e\\u0432\\nlet new_emails = [];\\nfor (let i = 0; i < api_emails.length; i++) {\\n  let found = false;\\n  for (let j = 0; j < db_emails.length; j++) {\\n    if (api_emails[i] === db_emails[j]) {\\n      found = true;\\n      break;\\n    }\\n  }\\n  if (!found) {\\n    new_emails.push(api_emails[i]);\\n  }\\n}\\nreturn new_emails;", "typing": true, "start_time": 356}, {"title": "Python", "color": "#38BDF8", "file": "find_emails.py", "code": "# \\u041f\\u043e\\u0438\\u0441\\u043a \\u0443\\u043d\\u0438\\u043a\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 email-\\u043e\\u0432\\n\\napi_set = set(api_emails)\\ndb_set = set(db_emails)\\n\\nnew_emails = list(api_set - db_set)", "typing": true, "start_time": 1856}]}	Подходит: сравнение двух реализаций, «просто против сложно», показ разницы подходов. Не использовать: для одного фрагмента кода (есть CodeExplain) или когда код не нужен в кадре вообще.
