9256	1289	{"windows": [{"title": "\\u0423\\u044f\\u0437\\u0432\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c (\\u0418\\u043c\\u043f\\u0440\\u043e\\u0432\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f)", "color": "#EF4444", "file": "legacy_bot.py", "typing": true, "code": "class NaiveAssistant:\\n    def process_query(self, user_input):\\n        # No context validation\\n        # No confidence checking\\n        # Hallucination risk is extremely high\\n        try:\\n            # Directly feed input to LLM\\n            response = self.llm.generate(\\n                prompt=user_input,\\n                temperature=0.9\\n            )\\n            return response.text\\n        except Exception as e:\\n            return \\"I don't know.\\"", "start_time": 400}, {"title": "\\u041d\\u0430\\u0434\\u0435\\u0436\\u043d\\u043e\\u0441\\u0442\\u044c (\\u042d\\u0441\\u043a\\u0430\\u043b\\u0430\\u0446\\u0438\\u044f)", "color": "#10B981", "file": "enterprise_agent.py", "typing": true, "code": "class EnterpriseAgent:\\n    def process_query(self, user_input, context):\\n        # 1. Semantic verification\\n        intent = self.classifier.analyze(user_input)\\n        \\n        # 2. Confidence scoring\\n        confidence = self.rag.evaluate_match(intent, context)\\n        \\n        if confidence < self.threshold:\\n            # 3. Strict escalation protocol\\n            logger.warning(f\\"Low confidence ({confidence}). Escalating.\\")\\n            return self.escalate_to_human(\\n                query=user_input, \\n                context=context\\n            )\\n            \\n        return self.llm.generate_safe(intent, context)", "start_time": 2400}]}
